// 本人有限页只从已经当场收到的信件进入；未到信的数量、主题与远方死者不在本页暴露。
#include "task_message_notice.hpp"
#include "resident/views/common_presentation.hpp"
namespace hanmo::resident {
Outcome<BoundaryValue> query_delivered_task_death_notices(const CommonStore& c,const TaskState& tasks,const TaskCatalog& catalog,const CommonCatalog& shared,const TaskMessageNoticeCatalog& policies,const TaskMessageNoticeState& state,const TaskMessageHandoffState& handoffs,const WitnessedDeathNoticeValidationRead& validate,Integer cursor){using V=BoundaryValue;const auto& observer=c.state().metadata.player_actor_id;if(!c.actor(observer))return {false,{},common_failure("UnknownPlayer").error};std::vector<StableId> received;const auto found=handoffs.observed_by.find(observer);if(found!=handoffs.observed_by.end())for(const auto& id:found->second){const auto* receipt=handoffs.receipts.find(id);if(!receipt)return {false,{},common_failure("TaskMessageHandoffObserverIndexMismatch").error};if(receipt->recipient_actor_id!=observer)continue;const auto bound=state.task_to_binding.find(receipt->task_id);if(bound!=state.task_to_binding.end())received.push_back(bound->second);}if(cursor<0||static_cast<std::size_t>(cursor)>received.size())return {false,{},common_failure("InvalidTaskMessageNoticeCursor").error};CommonPresentation presentation(c.state(),shared);V::Array rows;Integer next=cursor;for(;static_cast<std::size_t>(next)<received.size()&&rows.size()<16;++next){auto read=read_delivered_task_death_notice(c,tasks,catalog,shared,policies,state,handoffs,validate,observer,received[static_cast<std::size_t>(next)]);if(!read.ok)return {false,{},read.error};if(!read.value)return {false,{},common_failure("TaskMessageNoticeIndexMismatch").error};const auto& n=*read.value;auto deceased=presentation.display_name(n.decedent_actor_id),sender=presentation.display_name(n.sender_actor_id);rows.push_back(boundary::obj({{"decedent_name",V{deceased.ok?deceased.value:n.decedent_actor_id}},{"sender_name",V{sender.ok?sender.value:n.sender_actor_id}},{"binding_fact_id",V{n.binding_fact_id}},{"task_id",V{n.task_id}},{"source_lot_id",V{n.source_lot_id}},{"handoff_fact_id",V{n.handoff_fact_id}},{"death_fact_id",V{n.death_fact_id}},{"decedent_actor_id",V{n.decedent_actor_id}},{"sender_actor_id",V{n.sender_actor_id}},{"recipient_actor_id",V{n.recipient_actor_id}},{"issued_tick",V{n.issued_tick}},{"received_tick",V{n.received_tick}},{"explanation",V{StableId{"你已收到原亲历者委托送来的死亡文书；这不代表你已接受遗赠、继任或承担其债务。"}}}}));}StableId world;const char* digits="0123456789abcdef";for(auto b:c.state().identity.world_id){world+=digits[b>>4];world+=digits[b&15];}V::Dict page{{"ok",V{true}},{"observer_actor_id",V{observer}},{"source_identity",boundary::obj({{"world_id",V{world}},{"execution_epoch",V{c.state().identity.execution_epoch}},{"revision",V{c.revision()}},{"tick",V{c.tick()}}})},{"cursor",V{cursor}},{"rows",V{std::move(rows)}}};if(static_cast<std::size_t>(next)<received.size())page.emplace_back("next_cursor",V{next});return {true,V{std::move(page)},{}};}
}
